const b = $('Chat Webhook').first().json.body || {};
// the skill library is a data table now, so the agent's own improvements are live
const index = { skills: (($('Load Skills').first().json.rows) || []).map(r => ({
  id: r.skill_id, version: r.version, status: r.status, title_ar: r.title_ar,
  title_en: r.title_en, keywords: String(r.keywords || '').split(';').filter(Boolean),
  profile_id: r.profile_id, internal: String(r.internal) === 'true',
  allowed_services: String(r.allowed_services || '').split(';').filter(Boolean),
  approval_chain: String(r.approval_chain || '').split(';').filter(Boolean),
  auto_execute: String(r.auto_execute) === 'true', sla_hours: Number(r.sla_hours) || 48,
  body_md: r.body_md })) };
const skills = (index.skills || []).filter(s => s.status === 'approved' && !s.internal);
const listing = skills.map(s => ({ id: s.id, title_ar: s.title_ar, keywords: s.keywords }));
const prompt = ['أنت مصنّف نوايا لبوابة خدمات موظفين. طلب الموظف:', b.message || '',
  'المهارات المتاحة:', JSON.stringify(listing),
  'أعد JSON فقط: {"skill_id": "<id أو null>", "confidence": 0..1}. اختر null إذا لم يطابق الطلب أي مهارة بوضوح.'].join('\n');
return [{ json: {
  employee_id: b.employee_id || '', session_id: b.session_id || ('S-' + Date.now()),
  message: b.message || '', active_skill_id: b.active_skill_id || '',
  skills, listing,
  geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0, response_mime_type: 'application/json' } },
} }];

const out = [];
for (const item of $input.all()) {
  let text = '';
  try { text = item.json.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) {}
  const cleaned = text.replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim();
  let parsed = null;
  try { parsed = JSON.parse(cleaned); } catch (e) {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
  }
  out.push({ json: { gemini_text: cleaned, gemini_json: parsed, gemini_ok: !!parsed } });
}
return out;

const prep = $('Prepare Router').first().json;
let skill_id = prep.active_skill_id || '';
let confidence = 1;
if (!skill_id) {
  const r = $json.gemini_json || {};
  skill_id = r.skill_id && r.skill_id !== 'null' ? r.skill_id : '';
  confidence = typeof r.confidence === 'number' ? r.confidence : 0;
}
const skill = prep.skills.find(s => s.id === skill_id);
return [{ json: { ...prep, geminiBody: undefined, skill_id: skill ? skill.id : '',
  matched: !!skill && confidence >= 0.5,
  skill_meta: skill || null,
  services_list_ar: prep.skills.map(s => '• ' + s.title_ar).join('\n') } }];

function workingDays(startISO, endISO) {
  const s = new Date(startISO + 'T12:00:00Z'), e = new Date(endISO + 'T12:00:00Z');
  if (isNaN(s) || isNaN(e) || e < s) return null;
  let n = 0; const d = new Date(s);
  while (d <= e) { const w = d.getUTCDay(); if (w !== 6 && w !== 0) n++; d.setUTCDate(d.getUTCDate() + 1); }
  return n;
}
const j = $json.output || {};
const ctx = $('Compose System Prompt').first().json;
const prior = $('Compose System Prompt').first().json._rechecked === true || $json._rechecked === true;
let needs_recheck = false; const notes = [];
const p = j.transaction_preview;
if (p && ['preview', 'submitted'].includes(j.state) && ctx.skill_id === 'leave-request' && p.fields) {
  const det = workingDays(p.fields.start_date, p.fields.end_date);
  if (det !== null && p.working_days != null && +p.working_days !== det && !prior) {
    needs_recheck = true; notes.push('working_days يجب أن تكون ' + det);
  }
  if (prior && det !== null) p.working_days = det;
}
if (p && p.amount_aed != null) p.amount_aed = Math.round(+p.amount_aed * 100) / 100;
return [{ json: {
  reply_ar: j.reply_ar || '', state: j.state || 'info',
  transaction_preview: p || null, txn_id: j.txn_id || null,
  missing_fields: j.missing_fields || [],
  skill_id: ctx.skill_id, session_id: ctx.session_id,
  needs_recheck, recheck_notes: notes, _rechecked: prior,
} }];

const j = $json;
const prompt = ['راجع ردك: المدقق الحتمي وجد خطأً حسابيًا.', j.recheck_notes.join('؛ '),
  'ردك السابق:', JSON.stringify({ reply_ar: j.reply_ar, state: j.state,
    transaction_preview: j.transaction_preview, missing_fields: j.missing_fields }),
  'صحّح الأرقام وأعد JSON بنفس المخطط تمامًا دون أي نص آخر.'].join('\n');
return [{ json: { ...j, geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0, response_mime_type: 'application/json' } } } }];

const out = [];
for (const item of $input.all()) {
  let text = '';
  try { text = item.json.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) {}
  const cleaned = text.replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim();
  let parsed = null;
  try { parsed = JSON.parse(cleaned); } catch (e) {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
  }
  out.push({ json: { gemini_text: cleaned, gemini_json: parsed, gemini_ok: !!parsed } });
}
return out;

const prev = $('Deterministic Cross-Check').first().json;
const fixed = $json.gemini_ok ? $json.gemini_json : {
  reply_ar: prev.reply_ar, state: prev.state, transaction_preview: prev.transaction_preview,
  txn_id: prev.txn_id, missing_fields: prev.missing_fields };
return [{ json: { output: fixed, _rechecked: true } }];

function workingDays(startISO, endISO) {
  const s = new Date(startISO + 'T12:00:00Z'), e = new Date(endISO + 'T12:00:00Z');
  if (isNaN(s) || isNaN(e) || e < s) return null;
  let n = 0; const d = new Date(s);
  while (d <= e) { const w = d.getUTCDay(); if (w !== 6 && w !== 0) n++; d.setUTCDate(d.getUTCDate() + 1); }
  return n;
}
const b = $('Decide Webhook').first().json.body || {};
const txns = $('Read Transactions (decide)').all().map(i => i.json);
const emps = $('Read Employees (decide)').all().map(i => i.json);
const t = txns.find(r => r.txn_id === b.txn_id);
if (!t) return [{ json: { ok: false, error: 'TXN_NOT_FOUND' } }];
if (!String(t.status || '').startsWith('awaiting_'))
  return [{ json: { ok: false, error: 'NOT_PENDING', status: t.status } }];
const stage = t.current_approver;
const approver = emps.find(r => r.employee_id === b.approver_id) || {};
const owner = emps.find(r => r.employee_id === t.employee_id) || {};
// manager stage authorizes ONLY the employee's own manager; other stages match by role
const authorized = stage === 'manager' ? (owner.manager_id === b.approver_id)
  : (approver.role === stage);
if (!authorized) return [{ json: { ok: false, error: 'NOT_AUTHORIZED', stage } }];
const dec = String(b.decision || '').toLowerCase();
if (dec !== 'approve' && dec !== 'reject') return [{ json: { ok: false, error: 'INVALID_DECISION' } }];
const chain = String(t.approval_chain || '').split(';').filter(Boolean);
const pos = +t.chain_pos || 0;
let update = { txn_id: t.txn_id, decision_note: b.note || '', updated_at: new Date().toISOString() };
let side = null;
if (dec === 'reject') {
  update.status = 'rejected'; update.current_approver = '';
} else if (pos + 1 < chain.length) {
  update.status = 'awaiting_' + chain[pos + 1];
  update.current_approver = chain[pos + 1]; update.chain_pos = pos + 1;
} else {
  update.status = 'executed'; update.current_approver = ''; update.chain_pos = pos + 1;
  let pl = {}; try { pl = JSON.parse(t.payload_json || '{}'); } catch (e) {}
  if (t.skill_id === 'leave-request' && pl.start_date && pl.end_date) {
    const days = pl.working_days || workingDays(pl.start_date, pl.end_date) || 0;
    side = { kind: 'leave', employee_id: t.employee_id, leave_type: pl.leave_type || 'annual', days };
  }
  if (t.skill_id === 'it-access-request' && pl.system_id) {
    side = { kind: 'it', employee_id: t.employee_id, grant: pl.system_id + ':' + (pl.access_level || 'read') };
  }
}
return [{ json: { ok: true, update, side, txn: t, owner_email: owner.email || '',
  decision: b.decision, stage } }];

const j = $('Decide').first().json;
if (!j.side) return [];
if (j.side.kind === 'leave') {
  const bals = $('Read LeaveBalances (side)').all().map(i => i.json);
  const b = bals.find(r => r.employee_id === j.side.employee_id);
  if (!b) return [];
  const field = j.side.leave_type === 'sick' ? 'sick_used' : 'annual_used';
  return [{ json: { employee_id: b.employee_id, [field]: +b[field] + j.side.days } }];
}
if (j.side.kind === 'it') {
  const emps = $('Read Employees (side)').all().map(i => i.json);
  const e = emps.find(r => r.employee_id === j.side.employee_id);
  if (!e) return [];
  const roles = String(e.it_roles || '').split(';').filter(Boolean);
  if (!roles.includes(j.side.grant)) roles.push(j.side.grant);
  return [{ json: { employee_id: e.employee_id, it_roles: roles.join(';') } }];
}
return [];

const d = $('Decide').first().json;
return [{ json: {
  ts: new Date().toISOString(), session_id: 'approvals',
  employee_id: d.txn.employee_id, skill_id: d.txn.skill_id,
  service: 'notify_employee',
  request_json: JSON.stringify({ txn_id: d.txn.txn_id, decision: d.decision }),
  result_summary: 'حالة معاملتك (' + d.txn.type_ar + ') أصبحت: ' + d.update.status
    + (d.update.decision_note ? ' — ملاحظة: ' + d.update.decision_note : ''),
} }];

const d = $json;
const now = Date.now();
const emps = d.employees || [];
const byId = {}; for (const e of emps) byId[e.employee_id] = e;
const cases = [];
for (const t of (d.transactions || [])) {
  if (!String(t.status || '').startsWith('awaiting_')) continue;
  const ageH = (now - new Date(t.updated_at || t.ts).getTime()) / 36e5;
  const sla = +t.sla_hours || 48;
  if (ageH < sla * 0.5) continue;
  const owner = byId[t.employee_id] || {};
  const mgr = byId[owner.manager_id] || {};
  cases.push({ txn_id: t.txn_id, type_ar: t.type_ar, employee: t.employee_name,
    stage: t.current_approver, age_hours: Math.round(ageH * 10) / 10, sla_hours: sla,
    breached: ageH > sla, approver_email: t.current_approver === 'manager' ? (mgr.email || '') : '',
  });
}
return [{ json: { cases, case_count: cases.length, now: new Date().toISOString() } }];

const cases = $('Find Stale').first().json.cases;
const by = {}; for (const c of cases) by[c.txn_id] = c;
const out = [];
for (const dd of (($json.output || {}).decisions || [])) {
  if (dd.action === 'wait') continue;
  out.push({ json: { ...(by[dd.txn_id] || {}), ...dd, ts: new Date().toISOString() } });
}
return out; // empty = nothing to act on, chain ends here

return $input.all().map(i => ({ json: {
  ts: i.json.ts, session_id: 'sla-chaser', employee_id: '',
  skill_id: '', service: 'sla_' + i.json.action,
  request_json: JSON.stringify({ txn_id: i.json.txn_id, hours_late: i.json.age_hours }),
  result_summary: i.json.justification_ar || '' } }));

const d = $json;
const index = { skills: (d.skills || []).map(r => ({ id: r.skill_id, version: r.version,
  status: r.status, title_ar: r.title_ar, title_en: r.title_en,
  internal: String(r.internal) === 'true', created_by: r.created_by, updated_at: r.updated_at,
  allowed_services: String(r.allowed_services || '').split(';').filter(Boolean),
  approval_chain: String(r.approval_chain || '').split(';').filter(Boolean),
  sla_hours: Number(r.sla_hours) || 48 })) };
const txns = (d.transactions || []).filter(t => t.txn_id)
  .sort((a, b) => String(b.ts).localeCompare(String(a.ts)));
const today = new Date().toISOString().slice(0, 10);
return [{ json: {
  generated_at: new Date().toISOString(),
  kpis: {
    total: txns.length,
    today: txns.filter(t => String(t.ts).startsWith(today)).length,
    pending: txns.filter(t => String(t.status).startsWith('awaiting_')).length,
    executed: txns.filter(t => t.status === 'executed').length,
    rejected: txns.filter(t => t.status === 'rejected').length,
    minutes_saved: txns.filter(t => t.status === 'executed').length * 25,
  },
  transactions: txns.slice(0, 100),
  audit: (d.audit || []).slice(-60).reverse(),
  skills: (index.skills || []),
  memory: (d.memory || []).filter(m => m.status === 'active'),
  patches: (d.patches || []).sort((a, b) =>
    String(b.created_at).localeCompare(String(a.created_at))),
  learning: {
    memory_entries: (d.memory || []).filter(m => m.status === 'active').length,
    memory_chars: (d.memory || []).filter(m => m.status === 'active')
      .reduce((n, m) => n + String(m.content || '').length, 0),
    memory_budget: 2200,
    pending_patches: (d.patches || []).filter(x => x.status === 'pending').length,
    approved_patches: (d.patches || []).filter(x => x.status === 'approved').length,
  },
  employees: (d.employees || []).map(e => ({ employee_id: e.employee_id, name_ar: e.name_ar,
    name_en: e.name_en || '', role: e.role, department: e.department, manager_id: e.manager_id })),
  balances: d.balances || [],
} }];

const d = $json;
const now = Date.now();
// Only look at the recent slice: reflection is cheap because it is bounded.
const recent = (d.transactions || []).filter(t => {
  const ts = new Date(t.updated_at || t.ts).getTime();
  return !isNaN(ts) && (now - ts) < 24 * 3600 * 1000;
});
const audit = (d.audit || []).slice(0, 40);
const denials = audit.filter(a => String(a.result_summary || '').startsWith('DENIED'));
const batch = recent.map(t => ({ txn_id: t.txn_id, skill_id: t.skill_id,
  status: t.status, type_ar: t.type_ar, employee_id: t.employee_id,
  payload: t.payload_json, decision_note: t.decision_note }));
return [{ json: { batch, batch_size: batch.length,
  denial_count: denials.length,
  denials: denials.map(a => ({ skill_id: a.skill_id, service: a.service })),
  now: new Date().toISOString() } }];

const rows = $input.all().map(i => i.json);
const r = rows.find(x => x && x.skill_id === 'reflection') || {};
return [{ json: { body_md: r.body_md || '' } }];

